                remaining_time = deadline - time.time()
                if remaining_time <= 0:
                    # Terminate all remaining processes immediately
                    for _, remaining in list(self.processes.items()):
                        if remaining.is_alive() and isinstance(remaining, multiprocessing.Process):
                            try:
                                remaining.terminate()
                            except (ValueError, AttributeError):
